import json
p='17d1d78c-4f7c-43a3-aa25-5b20af6a6984.jsonl'
rows=[]
with open(p) as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: rows.append(json.loads(line))
        except: pass

def brief(r):
    t=r.get('type')
    m=r.get('message',{}) or {}
    c=m.get('content')
    parts=[]
    if isinstance(c,str): parts.append(('text',c))
    elif isinstance(c,list):
        for b in c:
            if not isinstance(b,dict): continue
            bt=b.get('type')
            if bt=='text': parts.append(('text',b.get('text','')))
            elif bt=='tool_use': parts.append(('tool:'+str(b.get('name')), json.dumps(b.get('input',{}),ensure_ascii=False)))
            elif bt=='tool_result':
                cc=b.get('content')
                s=cc if isinstance(cc,str) else json.dumps(cc,ensure_ascii=False)
                parts.append(('result',s))
    return parts

for i in range(2282, len(rows)):
    r=rows[i]
    if r.get('type') not in ('user','assistant'): continue
    for kind,txt in brief(r):
        txt=txt.strip()
        if not txt: continue
        if kind=='result' and len(txt)>700: txt=txt[:700]+' ...[trunc]'
        if kind=='text' and len(txt)>1800: txt=txt[:1800]+' ...[trunc]'
        if kind.startswith('tool:') and len(txt)>500: txt=txt[:500]+' ...[trunc]'
        print(f"\n--- [{i}] {r.get('type')} {kind} ---")
        print(txt)
EOF

